#[test]
fn test_ruby_vm_syntax_tree_calls_execution() {
    let output = run_example("ruby_vm/syntax_tree_calls.rb");
    assert_eq!(output, SYNTAX_TREE_CALLS_OUTPUT);
}

#[test]
fn test_ruby_vm_syntax_tree_calls_no_parens_execution() {
    let output = run_example("ruby_vm/syntax_tree_calls_no_parens.rb");
    assert_eq!(output, SYNTAX_TREE_CALLS_OUTPUT);
}

