#[test]
fn test_ruby_vm_syntax_tree_definitions_execution() {
    let output = run_example("ruby_vm/syntax_tree_definitions.rb");
    assert_eq!(output, SYNTAX_TREE_DEFINITIONS_OUTPUT);
}

#[test]
fn test_ruby_vm_syntax_tree_definitions_no_parens_execution() {
    let output = run_example("ruby_vm/syntax_tree_definitions_no_parens.rb");
    assert_eq!(output, SYNTAX_TREE_DEFINITIONS_OUTPUT);
}

