#[test]
fn test_ruby_vm_syntax_tree_strings_execution() {
    let output = run_example("ruby_vm/syntax_tree_strings.rb");
    assert_eq!(output, SYNTAX_TREE_STRINGS_OUTPUT);
}

#[test]
fn test_ruby_vm_syntax_tree_strings_no_parens_execution() {
    let output = run_example("ruby_vm/syntax_tree_strings_no_parens.rb");
    assert_eq!(output, SYNTAX_TREE_STRINGS_OUTPUT);
}

